'use client';
import { useEffect, useRef } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion, useSeconds } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { enter, Fold, Spin, Swap, Think, Tip } from '../lib/motion';
import '../designme.css';
import './thinking.css';

export interface ThinkingStep {
  /** What the agent does, like "Measure the plan cards" */
  label: string;
  /** running spins and shimmers, retry waits out a problem in amber, done turns into a check */
  state: 'running' | 'retry' | 'done';
  /** What the step found, or what it waits on, under it: "3 cards are off the 8px grid". Opens and crossfades when it changes */
  result?: string;
  /** More detail shown when you hover the result, like the measured values */
  resultTip?: string;
  /** How long the step took, like "1.3s", shown at its right once it is done */
  time?: string;
}

export interface ThinkingProps {
  steps: ThinkingStep[];
  /** Spins, counts seconds and keeps the trace open while true */
  running: boolean;
  /** Seconds to show. Leave it out to let it count while running */
  seconds?: number;
  /** The header while it runs, like "Checking the pricing page" */
  title?: string;
  /** The header once it is done: what the work came to, like "3 cards to fix, 2 changes planned". Defaults to the number of steps */
  summary?: string;
  /** Folds the trace away a moment after it finishes */
  collapseWhenDone?: boolean;
  /** Whether the trace is open. Leave it out to let the header toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/** A line that settles in place when its words change, sharpening out of a soft blur. While it shimmers it just takes the new words */
function Settle({ children, shimmer, className }: { children: string; shimmer: boolean; className?: string }) {
  const ref = useRef<HTMLSpanElement>(null);
  const prev = useRef({ text: children, shimmer });
  const reduce = useReducedMotion();
  useIsoLayoutEffect(() => {
    const el = ref.current, was = prev.current; prev.current = { text: children, shimmer };
    if (!el) return;
    // the shimmer draws the words in a clear colour; going straight to the solid colour stops it fading in from nothing
    if (was.shimmer && !shimmer){ el.style.transition = 'none'; void el.offsetWidth; requestAnimationFrame(() => { el.style.transition = ''; }); }
    if (shimmer || reduce || was.text === children) return;
    const bp = getComputedStyle(el).getPropertyValue('--dm-motion').trim() === 'bp';
    el.animate(bp ? [{ opacity: .6 }, { opacity: 1 }] : [{ opacity: .6, filter: 'blur(1.5px)' }, { opacity: 1, filter: 'blur(0)' }],
      { duration: bp ? 220 : 460, easing: bp ? 'steps(3, end)' : 'cubic-bezier(.22,1,.36,1)' });
  }, [children, shimmer]);
  return <span ref={ref} className={cx(shimmer && 'dm-shim', className)}>{children}</span>;
}

/** What a finished step found, written in a word at a time */
function Words({ text }: { text: string }) {
  const w = text.split(' ');
  return <>{w.map((x, i) => <span key={i} className="dm-w" style={{ animationDelay: `${i * 45}ms` }}>{x}{i < w.length - 1 ? ' ' : ''}</span>)}</>;
}

function Mark({ state }: { state: ThinkingStep['state'] }) {
  if (state === 'running') return <Spin />;
  // keyed so each new mark plays its entrance once
  return <span key={state} className="dm-enter" style={{ display: 'grid' }}><Icon name={state === 'retry' ? 'clock' : 'check'} size="xs" /></span>;
}

/** The live trace: each step the agent takes on a line that turns green as they finish, and what each found, then a header
    that says what the work came to, folded away. */
export function Thinking({ steps, running, seconds, title = 'Working on it', summary, collapseWhenDone = true, open, defaultOpen = true, onOpenChange, className }: ThinkingProps) {
  const counted = useSeconds(running && seconds === undefined);
  const secs = seconds ?? counted;
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  // once it finishes, the trace waits a beat and folds itself away
  useEffect(() => {
    if (running || !collapseWhenDone || !steps.length) return;
    const t = setTimeout(() => setOpen(false), 2500);
    return () => clearTimeout(t);
  }, [running, collapseWhenDone, steps.length]); // eslint-disable-line react-hooks/exhaustive-deps
  const done = !running && steps.length > 0;

  return (
    <div data-dm="" className={cx('dm-tk', className)} data-open={isOpen ? '1' : '0'}>
      <button type="button" className={cx('dm-tk-h', done && 'dm-tk-fin')} aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
        <span className="dm-tk-mark">{done ? <span key="ok" {...enter()} style={{ display: 'grid' }}><Icon name="ok" /></span> : <Think on={running} />}</span>
        <Settle className="dm-tk-title" shimmer={running}>{done ? summary ?? `${steps.length} ${steps.length === 1 ? 'step' : 'steps'}` : title}</Settle>
        <span className="dm-tk-time dm-num">{secs + 's'}</span>
        <Icon name="chev-d" size="xs" className="dm-tk-chev" />
      </button>
      <Fold open={isOpen} className="dm-tk-fold">
        <ol className="dm-tk-list" aria-live="polite">
          {steps.map((s, i) => (
            <li key={i} className={cx('dm-tk-st dm-enter', s.state === 'running' ? 'dm-run' : 'dm-' + s.state)}>
              <span className="dm-mk"><Mark state={s.state} /></span>
              <div className="dm-tx">
                <span className="dm-tk-ln">
                  <Settle className="dm-lab" shimmer={s.state === 'running'}>{s.label}</Settle>
                  {s.state === 'done' && s.time && <span key="t" className="dm-tk-dur dm-num dm-enter">{s.time}</span>}
                </span>
                <span className={cx('dm-res', s.result && 'dm-on')}>
                  {s.state === 'done' && s.result
                    ? <span key={'w' + s.result}>{s.resultTip ? <Tip label={s.resultTip}><span tabIndex={0} data-tip=""><Words text={s.result} /></span></Tip> : <Words text={s.result} />}</span>
                    : <Swap>{s.result ?? ''}</Swap>}
                </span>
              </div>
            </li>
          ))}
        </ol>
      </Fold>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Thinking ---------- */
/* the steps the agent takes, on a line that turns green as each one finishes; the step in hand turns in the accent with a
   soft halo, and what each step found writes itself in under it. The header ends as a summary of the work */
/* neither the trace nor the box it sits in anchors the page's scroll: a centred demo that grows would otherwise pull
   the page along with it */
.dm-stage-in:has(>.dm-tk){overflow-anchor:none}
.dm-tk{font-size:14px;width:100%;max-width:420px;margin-inline:auto;overflow-anchor:none}
/* on a card the trace keeps the room it will fill, so the header stays put as steps arrive */
.dm-stage-in>.dm-tk{min-height:inherit}
.dm-tk-h{display:flex;align-items:center;gap:10px;width:calc(100% + 16px);margin:0 -8px;padding:6px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));text-align:left;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-tk-h:hover{background:var(--dm-row)}}
.dm-tk-mark{width:18px;height:18px;flex:none;display:grid;place-items:center;color:var(--dm-accent-mark,var(--dm-accent));transition:color .3s}
.dm-tk-h.dm-tk-fin .dm-tk-mark{color:var(--dm-ok)}
.dm-tk-h.dm-tk-fin .dm-tk-mark .dm-i{animation:dm-tkpop .5s var(--dm-ease) backwards}
.dm-tk-title{flex:1;min-width:0;color:var(--dm-fg)}
.dm-tk-time{color:var(--dm-muted);font-size:13px}
.dm-tk-chev{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-tk[data-open="0"] .dm-tk-chev{transform:rotate(-90deg)}
.dm-tk-list{list-style:none;margin:0;padding:6px 0 0;display:flex;flex-direction:column}
.dm-tk-st{position:relative;display:flex;gap:10px;padding:6px 0}
/* the line from each step down to the next: grey, and green once the step above it is done */
.dm-tk-st:not(:last-child)::before,.dm-tk-st.dm-done:not(:last-child)::after{content:"";position:absolute;left:8.25px;top:29px;bottom:-5px;width:1.5px;border-radius:1px;background:var(--dm-line)}
.dm-tk-st.dm-done:not(:last-child)::after{background:color-mix(in srgb,var(--dm-ok) 55%,var(--dm-line));transform-origin:top;animation:dm-tkgrow .6s var(--dm-ease) backwards}
@keyframes dm-tkgrow{from{transform:scaleY(0)}}
.dm-tk-st .dm-mk{position:relative;width:18px;height:18px;flex:none;margin-top:1px;display:grid;place-items:center;border-radius:50%;color:var(--dm-muted);transition:background .32s,color .32s}
.dm-tk-st .dm-mk .dm-spin{width:10px;height:10px}
.dm-tk-st.dm-run .dm-mk{color:var(--dm-accent-mark,var(--dm-accent));background:var(--dm-accent-bg);animation:dm-tkhalo 1.8s var(--dm-ease-io) infinite}
.dm-tk-st.dm-done .dm-mk{background:var(--dm-ok-bg);color:var(--dm-ok)}
.dm-tk-st.dm-done .dm-mk .dm-i{animation:dm-tkpop .45s var(--dm-ease) backwards}
.dm-tk-st.dm-retry .dm-mk{background:var(--dm-warn-bg);color:var(--dm-warn);animation:dm-tkhalow 1.8s var(--dm-ease-io) infinite}
@keyframes dm-tkhalo{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
@keyframes dm-tkhalow{0%,100%{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 0%,transparent)}50%{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 6%,transparent)}}
@keyframes dm-tkpop{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:none}}
.dm-tk-st .dm-tx{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-tk-st .dm-tk-ln{display:flex;align-items:baseline;gap:var(--dm-s-2)}
.dm-tk-st .dm-lab{flex:1;min-width:0;color:var(--dm-fg);transition:color .32s}
.dm-tk-st.dm-done .dm-lab{color:var(--dm-fg2)}
/* how long the step took, once it is done */
.dm-tk-st .dm-tk-dur{flex:none;font-size:12px;color:var(--dm-muted)}
/* what a step found opens under it, a word at a time */
.dm-tk-st .dm-res{display:grid;grid-template-rows:0fr;font-size:13px;color:var(--dm-muted);transition:grid-template-rows .32s var(--dm-ease),color .32s}
.dm-tk-st .dm-res.dm-on{grid-template-rows:1fr}
.dm-tk-st .dm-res>span{overflow:hidden;min-height:0}
.dm-tk-st .dm-res .dm-w{display:inline-block;white-space:pre;animation:dm-tkword .42s var(--dm-ease) backwards}
@keyframes dm-tkword{from{opacity:0;transform:translateY(3px);filter:blur(2px)}}
.dm-tk-st.dm-retry .dm-res{color:var(--dm-warn)}
.dm-tk-st .dm-res [data-tip]{text-decoration:underline dotted var(--dm-faint);text-underline-offset:3px;cursor:default}
:root:not([data-style="soft"]) .dm-tk-st.dm-run .dm-mk:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .dm-tk-st.dm-retry .dm-mk:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .dm-tk-st.dm-run .dm-mk:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px var(--dm-accent-mark)}
:root:not([data-style="soft"]) .dm-tk-st.dm-done:not(:last-child):not(:where([data-style="soft"],[data-style="soft"] *))::after{background:var(--dm-ok);width:1px;left:8.5px}
:root:not([data-style="soft"]) .dm-tk-st:not(:last-child):not(:where([data-style="soft"],[data-style="soft"] *))::before{width:1px;left:8.5px;background:repeating-linear-gradient(var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .dm-tk-st.dm-done .dm-mk .dm-i:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .dm-tk-h.dm-tk-fin .dm-tk-mark .dm-i:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .dm-tk-st .dm-res .dm-w:not(:where([data-style="soft"],[data-style="soft"] *)){animation:dm-bpin .3s var(--dm-ease) backwards}
